import{z as p,x as A,o as t,c as C,q as l,j as i,D as E,d as o,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"分层编译","description":"","frontmatter":{"title":"分层编译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tiered-compilation.md","filePath":"cs/tiered-compilation.md","lastUpdated":1791063341000}'),d={name:"cs/tiered-compilation.md"};function B(m,a,T,c,u,h){const r=A("Mermaid");return t(),C("div",null,[a[2]||(a[2]=l('<h1 id="分层编译" tabindex="-1">分层编译 <a class="header-anchor" href="#分层编译" aria-label="Permalink to &quot;分层编译&quot;">​</a></h1><div class="epigraph"><p>第一层快而笨（解释器或基线 JIT），高层慢而狠（优化 JIT）。热点升层，冷代码不付顶级编译的代价。</p><footer>—— 据 Paleczny, Vick and Click, The Java HotSpot Server Compiler；HotSpot 分层编译说明整理</footer></div><p>上一课<a href="/cs/type-feedback">类型反馈</a> 在各层都可收集。缺口是<strong>多层</strong>：解释器 / C1 / C2（HotSpot 名）。基线：几乎不优化，生成快，插满 profile。C2：内联、逃逸、循环，贵。本课钉升层策略，JIT 逃逸下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只用 C2：启动慢。只用解释器：峰值差。分层：阈值 1 进 C1，更高进 C2。去优化可降回 C1。缺口是<strong>编译预算队列</strong>，不是单层方法 JIT。</p><p>代码缓存：高层码更大，挤掉冷码。</p><h3 id="层不是「cpu-特权环」" tabindex="-1">层不是「CPU 特权环」 <a class="header-anchor" href="#层不是「cpu-特权环」" aria-label="Permalink to &quot;层不是「CPU 特权环」&quot;">​</a></h3><p>Ring 0 是硬件；compilation tier 是 VM 策略。不要混。</p><p><span class="marginnote">HotSpot 论文与博客。Graal 作为另一顶层点名。本课策略，不写 C2 所有遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每层入口、OSR 入口。计数跨层继承或再收集。后台编译：应用继续在旧层跑，完成后原子换入口。</p>',11)),(t(),i(s,null,{default:E(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%20--%3E%20L1%5B%22%E5%9F%BA%E7%BA%BF%20JIT%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E4%BC%98%E5%8C%96%20JIT%22%5D%0A%20%20L2%20--%3E%20DEOPT%5B%22%E5%8E%BB%E4%BC%98%E5%8C%96%E5%8F%AF%E9%99%8D%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 PGO AOT：Graal Native Image 等把顶层提前，启动快峰值固定——点名对照，本课以在线分层为主。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"栈上有混合帧：C2 调 C1 调解释器。deopt 要认各层映射。不要死锁：编译线程要内存，应用线程要 CPU。",-1)),a[6]||(a[6]=e("p",null,"启发：平凡方法永不升 C2。",-1)),a[7]||(a[7]=e("p",null,"一个方法的热度决定它的命运：",-1)),(t(),i(s,null,{default:E(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E6%96%B9%E6%B3%95%E8%A2%AB%E8%B0%83%E7%94%A8%22%5D%20--%3E%20CNT%7B%22%E8%B0%83%E7%94%A8%E8%AE%A1%E6%95%B0%E8%BF%87%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20CNT%20--%3E%7C%22%E5%90%A6%22%7C%20INT%5B%22%E7%95%99%E5%9C%A8%E8%A7%A3%E9%87%8A%E5%99%A8%3A%20%E9%9B%B6%E7%BC%96%E8%AF%91%E6%88%90%E6%9C%AC%22%5D%0A%20%20CNT%20--%3E%7C%22%E6%98%AF%22%7C%20C1%5B%22%E8%BF%9B%20C1%3A%20%E5%BF%AB%E7%94%9F%E6%88%90%2C%20%E9%A1%BA%E5%B8%A6%E5%9F%8B%E6%8E%A2%E9%92%88%22%5D%0A%20%20C1%20--%3E%20HOT%7B%22%E6%8E%A2%E9%92%88%E6%98%BE%E7%A4%BA%E7%A1%AE%E5%AE%9E%E5%BE%88%E7%83%AD%3F%22%7D%0A%20%20HOT%20--%3E%7C%22%E6%98%AF%22%7C%20C2%5B%22%E8%BF%9B%20C2%3A%20%E5%86%85%E8%81%94%E4%B8%8E%E9%80%83%E9%80%B8%E7%AD%89%E6%BF%80%E8%BF%9B%E4%BC%98%E5%8C%96%22%5D%0A%20%20HOT%20--%3E%7C%22%E5%90%A6%22%7C%20STAY%5B%22%E5%81%9C%E5%9C%A8%20C1%22%5D%0A%20%20C2%20--%3E%20DEOPT%5B%22%E5%81%87%E8%AE%BE%E8%A2%AB%E8%BF%90%E8%A1%8C%E6%89%93%E8%84%B8%3A%20%E5%8E%BB%E4%BC%98%E5%8C%96%E9%99%8D%E5%B1%82%22%5D%0A%20%20DEOPT%20--%3E%20C1%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">直觉类比：分层编译像先出「草稿版翻译」保证能用，再对被反复引用的段落出「精校版」：草稿秒出、精校慢工，只花在热点上。大多数方法一辈子停在草稿层，真正吃掉九成时间的循环才值得精校。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写逃逸算法。后课默认：VM 用分层摊还。下一课 JIT 中的逃逸分析：顶层优化之一。</p><p><span class="marginnote">常见误区：初学者容易以为「既然 C2 性能最好，就该让所有方法都等 C2」——编译本身要占后台线程和代码缓存，冷方法升 C2 是纯亏：生成慢、占地方，还没人执行几次。分层的本质就是别为冷代码付顶级编译的账。</span></p><p>也不把分层当微服务分层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分层：快编译与狠优化分成多层，按热度升。</li><li>去优化可降层；代码缓存有限。</li><li>反馈在低层收集供给高层。</li><li>出处：Paleczny, Vick and Click；HotSpot 分层文档。</li></ul><p><span class="marginnote">术语翻译：「去优化（deopt）」就是优化编译时押注的假设（比如「这个字段一直是整数」）被运行打脸后，把执行点从优化码迁回低层等价代码的机制。有了它，高层才敢做激进优化——错了能退，而不是算错。</span></p>',8))])}const P=p(d,[["render",B]]);export{D as __pageData,P as default};
